<script setup>
import {clinicalTimestamp} from './clinicalDisplay.js';
defineProps({signatures:{type:Array,default:()=>[]},timeZone:{type:String,default:'America/Denver'}});
const role=value=>({provider:'Provider signature',supervisor:'Supervisor signature',author_acknowledgement:'Author acknowledgement'}[value] || 'Electronic signature');
</script>
<template><section v-if="signatures.length" class="note-signatures" aria-label="Electronic signatures"><article v-for="signature in signatures" :key="`${signature.role}:${signature.actorUserId}:${signature.signedAt}`"><h3>{{role(signature.role)}}</h3><p>Electronically signed by <strong>{{signature.signerLabel}}</strong></p><p>{{clinicalTimestamp(signature.signedAt,timeZone)}}</p><details><summary>Signature details</summary><p>Account {{signature.actorUserId}}<template v-if="signature.revisionId"> · Revision {{signature.revisionId}}</template><template v-if="signature.signatureId"> · Signature {{signature.signatureId}}</template></p><p v-if="signature.contentHash" class="signature-hash">Content hash: {{signature.contentHash}}</p><p v-if="signature.evidence">{{signature.evidence.ipAddressRecorded?'IP address recorded':'IP address not recorded'}} · {{signature.evidence.userAgentRecorded?'Device information recorded':'Device information not recorded'}}</p></details></article></section></template>
<style scoped>.note-signatures{border:1px solid #d7e5dd;border-radius:14px;padding:16px;background:#f3faf6;color:#203b4e}.note-signatures article+article{border-top:1px solid #d7e5dd;margin-top:14px;padding-top:12px}.note-signatures h3{font-size:14px;margin:0 0 8px}.note-signatures p{font-size:13px;line-height:1.5;margin:5px 0}.note-signatures details{font-size:12px;margin-top:10px}.signature-hash{overflow-wrap:anywhere}</style>
